import React from "react";
import Typed from "react-typed";
import myImage from "../img/myImage.png";

class About extends React.Component {
  render() {
    return (
      <section id="about" className="about-mf sect-pt4 route about-section">
        <div className="container">
          <div className="row justify-content-center">
            <div className="col-lg-10">
              <div className="box-shadow-full about-card">
                <div className="row">
                  {/* Left column: Image + Skills */}
                  <div className="col-md-5 text-center mb-4 mb-md-0">
                    <img
                      src={myImage}
                      className="img-fluid rounded-circle shadow-lg profile-img"
                      alt="Ehtesham Alam"
                    />
                  </div>

                  {/* Right column: About Me */}
                  <div className="col-md-7">
                    <div className="about-me">
                      <h5 className="title-left gradient-text mb-4">About Me</h5>

                      <div className="lead about-typed glow-text">
                        <Typed
                          strings={[
                            `
                            <strong style='color:#00e6ff;'>I’m Ehtesham Alam</strong>, a Full Stack Developer and Assistant Manager – Mobility Solutions at Mahindra Last Mile Mobility.<br/><br/>
                            I specialize in <strong style='color:#24b67e;'>scalable, efficient, and user‑friendly</strong> digital solutions bridging mobility and modern software.<br/><br/>
                            I bring hands‑on expertise in <strong style='color:#facc15;'>React, Node.js, Express, and cloud architectures</strong> with polished UI/UX dashboards.<br/><br/>
                            I hold a <strong style='color:#ff6ec4;'>B.Tech in Computer Science (NIT Warangal, Class of 2025)</strong> and completed a research internship at IIT ISM Dhanbad.<br/><br/>
                            <span style='color:#ff9800; font-weight:800;'>My Passions:</span><br/>
                            <strong style='color:#00e6ff;'>Coding Mastery</strong> 💻<br/>
                            <strong style='color:#24b67e;'>UI/UX Craft</strong> 🎨<br/>
                            <strong style='color:#facc15;'>Cloud Architect</strong> ☁️<br/>
                            <strong style='color:#ff6ec4;'>Problem Solver</strong> 🚀
                            `
                          ]}
                          typeSpeed={35}
                          backSpeed={20}
                          backDelay={5000}   // wait before erasing
                          loop={true}        // keep looping
                          smartBackspace={false}
                          showCursor={true}
                        />
                      </div>

                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>
    );
  }
}

export default About;
